ARTICLE_RE = re.compile(r'<article class="ptf-article">[\s\S]*?</article>')

for rel, article in PAGES.items():
    path = Path(rel)
    html = path.read_text(encoding="utf-8")
    new_html, count = ARTICLE_RE.subn(article, html, count=1)
    if count != 1:
        raise SystemExit(f"article not replaced in {rel}")
    path.write_text(new_html, encoding="utf-8")
    print(f"rewritten {rel}")
